def _测数(out, 兜底):
    """★2026-09-03·295第4轮立：从负测自印之首行里取它自己那个「M/N 全通」。
    ★★其立之由：三处 wrapper 把「3/3」「9/9」写死在码里，而 `负测_冷轮同判` 已扩至 7/7；
    全测遂逐日印「3/3 全通」——**器没印的数，令§一②不许说**，而这一处正是全测自己在说。
    ★★★故此後一律回印其自印之数；取不着方退回兜底，且兜底须带「★未取着」以示其疑。"""
    ls = [x for x in (out or '').split('\n') if x.strip()]
    for line in ([ls[0]] if ls else []) + (ls[-1:] if ls else []) + ls:
        m = re.search(r'(\d+/\d+)\s*全通', line)
        if m:
            return m.group(1)
    return '★未取着·' + 兜底

def run(desc, args, timeout=900, 带码=False):
    """跑一件器，返其印；**器崩即返 None**。

    ★2026-09-05·机制总审·八路之陪跑闸审所逮（其红在哪一行）：旧式把 stdout＋stderr 原样返回，
      而 chk_big_questions／chk_person_ledger／chk_two_ledger／chk_grand_audit／chk_huixiu／chk_duiwei（後二 1027 随回修、对位汰）／
      chk_object_roll_all 七项皆只在印里找「⛔」或某个数——**器一崩（traceback／超时），印里既无⛔亦无数，七项齐绿**。
      ★★实测（负测_全测崩绿.py ①）：以一段 traceback 灌此七项，旧式下 7/7 返 True。
      ★★★而这七项里有二项是全书唯二守「读者挂着的旧问」与「不出场之人」者——**它们崩了，81 项里照旧一个 ✓。**
    ★★★★故改二样：①stderr 里见 Traceback 即返 None（凡 hook 皆以 `out is None` 为「运行失败」）；
      ②超时先送 SIGINT 再 kill——**旧式 SIGKILL 令子进程之 finally 不跑，负测在真仓库上改的档就留在盘上**
      （同审之第11条·复现：timeout 杀後档留 MUTATED）。
    ★★★★★而其限（§一⑤）：本函只认「崩」；一件器不崩而印错，仍须各 hook 自验其项名。"""
    import signal
    try:
        p = subprocess.Popen([sys.executable] + args, cwd=ROOT, env=ENV,
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        try:
            out, err = p.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            try:
                p.send_signal(signal.SIGINT)
                out, err = p.communicate(timeout=15)
            except subprocess.TimeoutExpired:
                p.kill()
                p.communicate()
            return None
        if 'Traceback (most recent call last)' in (err or ''):
            return None
        return ((out or '') + (err or ''), p.returncode) if 带码 else (out or '') + (err or '')   # 带码：X43⑥ 自测之项须看 rc
    except Exception:
        return None


def _留字快照():
    """★负测留字之查（2026-09-05·机制总审·八路之陪跑闸审第11条）：
    十余份负测在真仓库上改档再复原（FS认账改 canon 之 due、两册对限改到期账、器物点名删 _器物.md……），
    ★而一份负测若中途崩了或被超时杀了，复原那一步不跑，改动就留在盘上——**下一坐拿它当真账。**
    ★★故全测起手先给 设定／版本／正文 每一档记一个 sha256，跑毕再记一回，二者之差即「留字」。
    ★★★实测（2026-09-05）：正常一跑 83 项，内容有变之档 0——故此查常态为零，一响即真。"""
    import hashlib
    snap = {}
    for top in ('设定', '版本', '正文'):
        for dp, dn, fn in os.walk(os.path.join(ROOT, top)):
            if '__pycache__' in dp:
                continue
            for x in fn:
                p = os.path.join(dp, x)
                # ★0924：自进化环之脉（每时由自走／环自写·非负测所改）不入留字之照——
                #   ⛔只免这三档之名，别档一字之变照旧红（推闸 0924 晚被这两档之「留字」拦过一回）
                if os.path.relpath(p, ROOT) in ('设定/自进化环.log', '设定/自进化环_挂账.json', '设定/_自进化环_推.out'):
                    continue
                try:
                    snap[os.path.relpath(p, ROOT)] = hashlib.sha256(open(p, 'rb').read()).hexdigest()
                except Exception:
                    pass
    return snap


def _有席在跑():
    """★0910·作者令「机制不许有 bug」而本查当日被逮出一处真病：
    **它分不出「一份负测偷改了仓库」与「另一席正大光明在写第 310 章」这两件事。**
    ★★而这两件事的差别，在盘上是看得见的：心跳锁在／并发指纹在／末章尚无席记——
    三样中有一样，就是**带席而跑**。
    ★★★**本函不压红，只把话说清楚**：带席而跑时，留字之报转黄并写明是哪几档、为什么；
    　　仓里安静时（无席），它照旧判红——**它要防的那一样，正是在安静时发生的。**
    """
    import glob as _g
    凭 = []
    # ⛔**2026-09-13 同 ㊟ 之法再治一盏**：**旧式只问「`_心跳.json` 这个档在不在」**
    #   ——**而撤锁不删档，它只把「章」写成空**；**故自立心跳之日起，这一凭就一直亮着。**
    #   ★**今问心跳之实，不问档之在**：**章为空＝已撤锁**｜**逾四十五分钟＝其坐已死**
    #   （**限之数不在此处写死，自 `工具/心跳.py` 之 `限 = ` 一行现取**——**本册 ㊖：
    #   判据里不许出现任何「今天才成立」的东西，一个抄来的数也是**）。
    _hb = os.path.join(ROOT, '_心跳.json')
    if os.path.exists(_hb):
        try:
            import json as _j
            import re as _re2
            import time as _t
            _d = _j.load(open(_hb, encoding='utf-8'))
            _s = open(os.path.join(ROOT, '工具', '心跳.py'), encoding='utf-8').read()
            _m = _re2.search(r'^限\s*=\s*(\d+)\s*\*\s*60', _s, _re2.M)
            _lim = int(_m.group(1)) * 60 if _m else 45 * 60
            _age = int(_t.time()) - int(_d.get('时', 0))
            if _d.get('章') is not None and _age <= _lim:
                凭.append('心跳锁在（%d 分钟前报到）' % (_age // 60))
        except Exception:
            凭.append('心跳读不出（作有席论）')
    # ⛔**2026-09-13 去掉「并发指纹在」这一凭**（体检账 ㊟）：
    #   **那一套设施本仓早已自书「建于未经证实之前提，留而不用」**
    #   （`跑轮.py:306`／`十轮精进.py:301` 逐字）——**留而不用，即没有人去清它**；
    #   ★**0913 盘上三份指纹，两份係 08-27 与 09-09 之陈迹**：
    #   **於是「带席而跑」这一句，自那两天起就一直是亮的。**
    #   ⛔**一个永远亮着的灯，不报任何事**：**它只是把「这一回不算数」这句话，
    #   常年挂在每一次全测的头上**（与本册 ㊛ 同骨之反面：**那一道从来没报过，这一道从来没灭过**）。
    #   ★★**故其凭只留两样**：**心跳锁**（**权威·有四十五分钟之限，且有 `--收` 明口**）
    #   与**末章尚无席记**（**自磁盘现算，不留残迹**）。
    #   ★★★**并同日把那几份陈指纹清掉**：**留而不用者，不许再当凭据。**
    try:
        # ★**末章须自正文取，不许自版本目录取**：版本底下有 第999章 这样的试样目录，
        #   拿它当末章，会让本函永远说「有席在跑」——**那就等於把这道闸悄悄关掉了。**
        末 = len([x for x in os.listdir(os.path.join(ROOT, '正文')) if x.endswith('.md')])
        # ★若正文少了一档，末会偏小 → 去查一个早已封版之章 → 查不到凭 → 本函说「无席」→
        #   留字照旧判红。**这个方向是安全的**：宁可严，不可把闸悄悄关掉。
        if 末:
            if not os.path.exists(os.path.join(ROOT, '版本', '第%d章' % 末, '_席记.json')):
                凭.append('第%d章尚无 _席记.json（席未走完）' % 末)
    except Exception:
        pass
    return 凭


def _留字之差(before):
    after = _留字快照()
    changed = sorted(p for p in after if p in before and after[p] != before[p])
    added = sorted(p for p in after if p not in before)
    gone = sorted(p for p in before if p not in after)
    return changed, added, gone


def _器印之头(out, 头, 名):
    """★2026-09-05·机制总审（八路·陪跑闸审第1、2条之「印错之路」）：run() 只认「崩」；一件器不崩而印错（改了标签／半路 sys.exit／读错档）
    则七项 hook 只索「⛔」或某数，取不着即绿。★★故各 hook 先索器自印之头（其律§一⑤：绿只及於器自印之项名）——头不在，即「器未出声」，红。
    返回 None 表示头在；否则返回 (False, 说明)。"""
    if out is None:
        return False, '运行失败'
    if 头 not in (out or ''):
        return False, '器未出声（无其自印之头「%s」）——%s' % (头, (out or '').strip().split('\n')[-1][:60] or '空印')
    return None


def chk_selftest():
    out = run('检察官自测', ['工具/小说检察官.py', '--selftest'])
    m = re.search(r'规则回归:(\d+)/(\d+)；契约负测:(\d+)/(\d+)；项目接线:(\S+?)；末章硬闸:(\S+)', out)
    if not m:
        return False, '未取到自测结论行'
    a, b, c, d, e, f = m.groups()
    ok = (a == b and c == d and e == '通过' and f.startswith('通过'))
    return ok, '规则回归%s/%s 契约负测%s/%s 接线%s 末章硬闸%s' % (a, b, c, d, e, f)


def chk_doctor():
    out = run('医生', ['工具/小说检察官.py', '--doctor'])
    m = re.search(r'医生结论: ERROR=(\d+)', out)
    if not m:
        return False, '未取到医生结论'
    return m.group(1) == '0', 'ERROR=%s' % m.group(1)


def chk_shilun():
    """跑轮负测（存版之闸·端到端·漂移哨·造式之总核·拦停旗之生灭；1027 汰十三轮诸段，二百余秒→二秒）。"""
    out = run('跑轮负测', ['工具/跑轮.py', '--自测'])
    if out is None:
        return False, '运行失败'
    m = re.search(r'负测（含端到端真跑）：(\d+)/(\d+)', out)
    if not m:
        m = re.search(r'负测：(\d+)/(\d+)', out)
    if not m:
        return False, '未取到负测结论'
    return m.group(1) == m.group(2), '%s/%s' % m.groups()


