def chk_version_fingerprint():
    """版档指纹（2026-09-17 立·见 工具/版档指纹.py／机制体检账 七十八）——
    **台账自书之 `soft.净重` 对 `vNN.md` 实算**。
    ★与 `净重对表` 同族而更重一层：**那一道量的是人手写进施工表的数，
    　这一道量的是器当场算出来又自己存下的数**——**器算的与器存的对不上，其事更重。**
    ★★⛔**本项只报不拦**，其由逐条在器之档首：
    　`save()` 之形係 `hard, soft = score(txt)` 而後写 `vNN.md`——**存版当场绝无可能不符**；
    　**而版档之 git 史看不见**（一章诸版档尽在其封版席那一个提交里头一回落地），
    　**故「几时分的家」今日答不出**；**且不知该信哪一样**（档是回退之据，数是轮记之据）。
    　**判不死的就别做成闸**——交 `MECH-345-版档指纹` 当面裁。
    ★★★⛔**故本项之红只有一样：那个器自己坏了**（自测不过／跑不起来）。
    　⛔**不许拿「今日不符几处」当判据**——**今日是二十五，明日不是**（㊸）。"""
    neg = run('版档指纹·自测', ['工具/版档指纹.py', '--自测'])
    if neg is None or '10/10' not in neg:
        return False, (neg or '').strip().split('\n')[-1] or '自测运行失败'
    # ★1103 X59：旧版·不复之裁（设定/版档指纹_裁.json）之内只报；裁外之新不符／新无档 --闸 拦（0924 起 save() 一 txt 出数与档）
    _r = run('版档指纹', ['工具/版档指纹.py', '--闸'], 带码=True)
    if _r is None:
        return False, '运行失败'
    out, _rc = _r
    if _rc != 0:
        _新 = [x.strip() for x in out.split('\n') if x.strip().startswith('⛔新')]
        return False, '裁外有新不符 %d 处（器之病，逐条查其存版之路）：%s' % (len(_新), '；'.join(_新[:3]))
    ln = [x.strip() for x in out.split('\n') if '可比版档' in x]
    return True, (ln[0] if ln else '已跑') + '｜裁内只报、裁外拦｜自测 10/10'


def chk_draft_gate_day():
    """起草闸·乙层之日号（2026-09-08 二治·见 工具/负测_起草闸.py）。
    ★这一项守的不是「会不会报红」，是**印给人看的那个数对不对**。
    　乙层【一】那一栏告诉席「本章为第N天，你这处『昨天』指第N-1天」，
    　而相对日词一路占全书回修之 18%，是头号坑。**它印错，席就照着错数去答题。**
    ★★旧式两病（0908 由 290 与 293 两席各自逮出）：①不认「第N日」（暗线诸章章首之式）；
    　②字集无「零」（「第一百零四天」不匹配）。二者皆令闸跳过章首，取到後文回指之日。
    ★★★上盘一量：**全书 305 章里 41 章（13.4%）旧式所印之日与真日不同**，
    　其中 20 章旧式一个日子也认不出；最远者 289 印 24 而实 102、303 印 45 而实 109。
    ★★★★**一个会喊狼的核对器比没有更糟；而一个会报错数的告示牌，比没有告示牌更糟——
    　因为人会照它答题。** 故此器往後凡加「只报不判」之栏，每一栏都要有一条负测钉住它印的那个数。"""
    out = run('起草闸·自测', ['工具/起草闸.py', '--自测'])
    if out is None or '自测 8/8' not in out:
        return False, (out or '').strip().split('\n')[-1] or '自测未过'
    neg = run('负测·起草闸', ['工具/负测_起草闸.py'])
    if neg is None or '全通' not in neg:
        return False, (neg or '').strip().split('\n')[-1] or '负测运行失败'
    return True, ('乙层之日号全书逐章认得出（暗线「第N日」与「零」皆认，章首之日胜过後文回指）'
                  '｜自测 8/8｜负测_起草闸 全通'
                  '（旧式对 290 印 93、对 293 印 99，全书 41 章印错；今式逐章对）')


def chk_highlight_present():
    """亮点在（2026-09-06 晚立·见 工具/亮点在.py）——**骨记在不在**。
    ★其立之由：246 之修席进场时发现 246 一章根本没有【本章亮点】段，
    　而 亮点对表 与 起草闸甲层 照样报全绿——三路皆以 `if '【本章亮点】' not in txt: return` 起手，
    　**无段即无判据，於是无段就是全绿**。此为「绿而不实」之**第五种**：
    　有位、红得起来、看得见、也接进了「过不过」那一句，
    　**可遇上「整样东西不在」的时候，它是空过，不是判红**。
    ★★其群与其不认（令§六④）：认第 109 章以後之章（本书 197 章），骨记须恰一段；
    　1—108 章共 100 章无骨记，係立式以前之旧稿，**不认**——
    　若一并判红，此器天天红一百处，就成了没人看的红。那一批记在 机制总审§二十六。
    ★★★它红在哪一行（令§十三）：立此器之日红四处——280／281／282／283，同日补齐。
    ⛔★★★★★**2026-09-23·限362 补一路（本坐当日拆「赤手无负测」时所逮之系统病）**：
      ★**盘上多样器各自带着一份 `自测()`，而全测通篇无一格跑它**——
        **逐样亲数得九样**（起手哨／含拍／FS闸／亮点在／净重对表／质量三闸／字数闸 等）；
        ⛔**於是那几十格逐日躺着，谁也不知道它们今日还过不过得去。**
      ★★**今补**：**本格先跑 `--自测`，不满格即红；再跑其报。**
      ⛔**此改令本格更严，不更宽。**
      ★★★**并及其限**：**跑得过它自己那几格，⛔不等於它测着了什么**——
        **那是它自己造的局；一份真负测该拿「真犯过此病之原物」去撞它**（令§一⑤）。
        """
    _zi = run('亮点在·自测', ['工具/亮点在.py', '--自测'])
    if _zi is None:
        return False, '自测运行失败'
    import re as _r0
    _mz = _r0.search(r'自测 (\d+)/(\d+)', _zi)
    if not _mz:
        return False, '自测未见其数'
    if _mz.group(1) != _mz.group(2):
        return False, '自测未满格 %s/%s' % (_mz.group(1), _mz.group(2))
    out = run('亮点在', ['工具/亮点在.py'])
    if out is None:
        return False, '运行失败'
    if '⛔' in out:
        return False, [x.strip() for x in out.split('\n') if '⛔' in x][0]
    ln = [x.strip() for x in out.split('\n') if '✓' in x]
    return True, (ln[0] if ln else '全绿') + '｜W35：负测_亮点在已退（其格由 --自测 管）'


