def chk_起手哨():
    """起手哨：连着几章拿日号起手（2026-09-22 立·见 `工具/起手哨.py`）。

    ★**其所以入册**：`起手账` 自 0919 起全靠人手逐章转交「327—351 连 25 章」这个数——
    ⛔**盘上没有一道器在数它**；**352 之治落地之後，更无一道器看着它别再回去。**

    ⛔★★★★★**2026-09-23·限362 补一路（本坐当日拆「赤手无负测」时所逮）**：
      ★**本器自带一份 `自测()`（10 格·其④格自造一局验「日词须在句首」那一道界）**，
        ⛔**而本格从前只跑它的『报』，一次也没有跑过它的『测』**——
        **於是那十格逐日躺着，谁也不知道它们今日还过不过得去。**
      ★★**今补**：**先跑 `--自测`，不满格即红；再跑其报。**
      ⛔**此改令本格更严，不更宽**：**它此後多问一句「你那一套格子今日还立得住么」。**
      ★★★**并及其限**：**跑得过它自己那十格，⛔不等於它测着了什么**——
        **那十格是它自己造的局；一份真负测该拿「真犯过此病之原物」去撞它**
        （令§一⑤）。**本器至今没有那样一份**（`册_0923_赤手无负测之拆数.md` §六之表，
        **起手哨係「盘上一份点名此器之负测也没有」那八样之一**）。
    """
    _zi = run('起手哨·自测', ['工具/起手哨.py', '--自测'])
    if _zi is None:
        return False, '自测运行失败'
    import re as _r
    _m = _r.search(r'起手哨·自测 (\d+)/(\d+)', _zi)
    if not _m:
        return False, '自测未见其数'
    if _m.group(1) != _m.group(2):
        return False, '自测未满格 %s/%s' % (_m.group(1), _m.group(2))
    out = run('起手哨', ['工具/起手哨.py'])
    if out is None:
        return False, '运行失败'
    for l in out.split('\n'):
        if l.strip().startswith('⛔'):
            return False, l.strip()
    尾 = [l.strip() for l in out.split('\n') if l.strip().startswith('✓')]
    return True, ('自测 %s/%s｜' % (_m.group(1), _m.group(2))
                  + (尾[0] if 尾 else '过')
                  + '（日起手係本书常式 89.9%，本器只看串之长；'
                    '★其负测 2026-09-24 已立：`工具/负测_起手哨.py` 19/19，'
                    '钉着串之算、日词须在句首、自352门18係写死之数）')


def chk_push_gate():
    """推闸负测（2026-08-28立·见 工具/负测_推闸.py）：X55 分等——读者可见之红恒拦、只器之红放行而入账。
    ⛔1027 汰跑轮档／封版档之放行口（旧推闸）：旧式回灌（97286329 之全测）认账即放 FS沉默闸，新式恒拦——故非陪跑。"""
    out = run('负测·推闸', ['工具/负测_推闸.py'])
    if out is None:
        return False, '运行失败'
    import re as _r
    m = _r.search(r'负测 (\d+) 项，过 (\d+)，坏 (\d+)', out)
    if not m:
        return False, '未见其数'
    tot, ok, bad = (int(x) for x in m.groups())
    if bad or ok != tot:
        _b = [ln.strip() for ln in out.splitlines() if '⛔' in ln]
        return False, '；'.join(_b[:3]) or '%d/%d' % (ok, tot)
    return True, '%d/%d 全通' % (ok, tot)


