def _简测(名, 脚本):
    """★共用之壳：跑一份「N/N 全通」式负测，取其末行之数。"""
    out = run(名, [脚本])
    if out is None:
        return False, '运行失败'
    import re as _r
    m = None
    for _m in _r.finditer(r'(\d+)/(\d+)\s*(全通|⛔未过)', out):
        m = _m
    if not m:
        return False, '未见其数'
    ok, tot = int(m.group(1)), int(m.group(2))
    if ok != tot:
        _b = [ln.strip() for ln in out.splitlines() if ln.strip().startswith('⛔')]
        return False, '%d/%d｜%s' % (ok, tot, '；'.join(_b[:3]))
    return True, '%d/%d 全通' % (ok, tot)


def chk_bigq_neg():
    """负测·大问挂账（八造·2026-09-03 立·见 工具/负测_大问挂账.py）。
    〔1119 死规之审·gates17〕并验全测之读（`_大问之判`）：逾自定之限而自其限以来册上有判行者只报 ⚠；
      无判行、判在限前、由不足、光写「还」、展期之新限已逾、无挂账者，照红（守牙）。"""
    ok, 语 = _简测('负测·大问挂账', '工具/负测_大问挂账.py')
    案 = _大问判之负测()
    坏 = [名 for 名, 过 in 案 if not 过]
    if not ok or 坏:
        return False, '%s%s' % (语, ('｜全测之读坏：%s' % '；'.join(坏[:3])) if 坏 else '')
    return True, '%s｜全测之读 %d/%d 全通' % (语, len(案), len(案))


