def _分量之判(out2):
    """★把 `分量闸` 正路之印读成一个判：(过否, 其语)。⛔**单拆出来，好教负测拿得住它**
    （`工具/负测_分量闸之读.py`·2026-09-23·限359 同日立）。"""
    import re as _r
    _真红 = _r.search(r'⛔ 分量闸：(\d+) 章不足而无豁免', out2)
    olds = _r.findall(r'⚠第(\d+)章：净重', out2)
    if _真红:
        reds = _r.findall(r'⛔第(\d+)章：净重 \d+ ＜ \d+（[^）]*），且施工表无', out2)
        return False, ('⛔不足而无豁免：第%s章' % '、第'.join(reds or [_真红.group(1) + '（其数）']))
    # 〔1119 死规之审·gates6〕唯「<2000 铁底而无豁免」红（上之 _真红·作者 0722 圣经:106-107／0817 施工表:4684「严禁为任何字数线凑字」）；
    #   暗线之厚（⛔末五篇暗线）、额破期间又认欠、认欠之额——俱 2000 以上之线，改只报 ⚠：其行照取、照印於本格之语，⛔return False。
    #   （旧 0924 裁「额破期间又认欠 → 红」随之只报；闸之新印 ⚠末五篇暗线／⚠额破之窗内又认／⚠认欠之额已破 一并接得着。）
    def _其行(p):
        _x = _r.search(p, out2)
        return _x.group(0).strip()[:90] if _x else ''
    _信 = []
    if _r.search(r'[⛔⚠]末五篇暗线', out2):
        _信.append('⚠暗线之厚：%s' % _其行(r'[⛔⚠]末五篇暗线[^\n]*'))
    if _r.search(r'额破(?:期间|之窗内)又认', out2):
        _信.append('⚠额破期间又认欠：%s' % _其行(r'[^\n]*额破(?:期间|之窗内)又认[^\n]*'))
    if _r.search(r'[⛔⚠][^\n]*认欠之额', out2):   # 俱只报，旧「额破·只报不拦」之免已无所免
        _信.append('⚠认欠之额已破：%s' % _其行(r'[⛔⚠][^\n]*认欠之额[^\n]*'))
    return True, ('新章无 <2000 铁底而未豁免者（<带只报·旧章只报不拦 %d 章·其账在 设定/分量欠账.md）%s'
                  % (len(olds), ''.join('｜%s（只报）' % x for x in _信)))


