    if not m or m.group(1) != m.group(2):
        return False, '自测未满格：%s' % (m.group(0) if m else '未见其数')
    out2 = run('清偿章哨', ['工具/清偿章哨.py'])
    if out2 is None:
        return False, '正路运行失败'
    reds = _r.findall(r'⛔(\S+?)（其章', out2)
