def chk_yaohe():
    """★咬合哨（2026-09-14 立）：**331 起，每五章之内须有一章其事係「两件事咬在一起」。**
    ⛔**其所由来**：0913 三把尺指同一处——`净重趋`（顶 7,076→今 2,216）｜`重出趋`（325:14.4／327:24.1）｜
      `书级体检`②（同型「长」连锁 13 章）——**这一段书太匀了**；
      ★**其裁已落**（治在事之择不在字数），**而那一条裁立了一日，盘上没有一只手在数它**（㊛ 之骨）。
    ★★**其认与 `悬念哨` 之第二路同式**：**骨记里明写一行「咬合：…」并带其据（≥8字）**；
      ⛔**空口一行不算**；⛔**而器不判「咬得好不好」——那只有读的人判得了**，**它只数「有没有一章报过」。**"""
    out = run('咬合哨·自测', ['工具/咬合哨.py', '--自测'])
    if out is None:
        return False, '运行失败'
    import re as _r
    m = _r.search(r'自测 (\d+)/(\d+)', out)
    if not m or m.group(1) != m.group(2):
        return False, '自测未满格：%s' % (m.group(0) if m else '未见其数')
    out2 = run('咬合哨', ['工具/咬合哨.py'])
    if out2 is None:
        return False, '正路运行失败'
    reds = _r.findall(r'⛔ 第(\d+)—(\d+)章五章之内一章也没有报过', out2)
    if reds:
        return False, ('⛔满窗空着：%s' % '、'.join('%s—%s' % x for x in reds))
    return True, ('%s·%s' % (m.group(0),
                             '未起役（尚未写到331）' if '未起役' in out2 else '无一个满窗空着'))


def chk_suspense(): 
    """★悬念哨（2026-09-13 立）：**三条主账各自之形皆写死「每三章至少一处」，而盘上至今没有一只手在数它。**
    ⛔**0913 头一回跑之实**：**SUS-A·那六天 末见第315章（隔13章）｜SUS-C·照着做 末见第318章（隔10章）。**
    ★**SUS-C 之难在其形**：**须由格式与工夫排出，不许把「给谁」答死**——**故它本来就不该有一个固定的词**，
      **任何数词之器都数不着它**；⛔**故哨为它开第二路**：**骨记里明写一行「SUS-C·本章复提：…」并带其据（≥8字）即算一处**
      （**⛔空口一行不算**·负测⑤格钉住）。
    ★★**本格之判**：**逾限者，其条须在 `到期账` 里挂一个「哨」之章（改挂到走得到的那一章）**；
      ⛔**挂了才算写明卡在哪一条**；**一笔逾限而账上无哨，当场红。**
    〔1119 死规之审·gates15／prompts6〕「每三章至少一处」係配额（为过哨插句：472:123、大审470 #19）：
      逾限而账上无哨、逾限而其哨已朽 → 只报 ⚠（其距照印，久空由段庭裁续、收或任其沉）；自测未满格、跑不起、判不出 → 照红（器之完整仍守）。"""
    out = run('悬念哨·自测', ['工具/悬念哨.py', '--自测'])
    if out is None:
        return False, '运行失败'
    import re as _r
    m = _r.search(r'自测 (\d+)/(\d+)', out)
    if not m or m.group(1) != m.group(2):
        return False, '自测未满格：%s' % (m.group(0) if m else '未见其数')
    import sys as _sys, os as _os, importlib as _il
    _sys.path.insert(0, _os.path.join(ROOT, '工具'))
    try:
        哨 = _il.import_module('悬念哨')
        末, 报 = 哨.判()
    except Exception as e:
        return False, '判不出：%s' % e
    import json as _j, io as _io
    账 = _j.load(_io.open(_os.path.join(ROOT, '设定', '到期账.json'), encoding='utf-8'))['items']
    哨章 = dict((x['id'], x.get('哨')) for x in 账)
    # ★1015（392 逮）：旧只问「有哨否」——SUS-B 哨 392，392 写毕未出而照绿；今哨须在末章之後（已写过之章不算挂）
    def _哨在前(v):
        try:
            return int(v) > 末
        except Exception:
            return False
    坏 = [k for k, 末见, 距, bad in 报 if bad and not _哨在前(哨章.get(k))]
    if 坏:
        # 〔1119 死规之审·gates15〕逾限而账上无哨 → 只报 ⚠（⛔return False）：哨之逼即为过哨插句之械（其语⛔书「⚠」紧接「逾限」——废「器红逾限不拦」之去证无文）
        return True, ('%s·⚠距逾其限而账上无哨（只报·1119 死规之审）：%s'
                      % (m.group(0), '、'.join('%s(末见%d·距%d章)' % (k, 末见, 距)
                                              for k, 末见, 距, bad in 报 if k in 坏)))
    # ⛔★★★★★2026-09-23·限362 补第二问：**一个已经过去的哨不是哨，是碑。**
    #   ★**其所由来·今日之实**：`悬念哨` 印「SUS-A 末见339·隔23章｜SUS-B 末见344·隔18｜SUS-C 末见339·隔23」
    #     （限皆为 3），**而本格照旧绿**——**其由只一样：它只问「挂没挂哨」，不问「那个哨过去了没有」。**
    #   ★★**逐条亲取其哨**：**SUS-A→344｜SUS-B→350｜SUS-C→330**——**三个哨俱在末章（362）之前**；
    #     **即：三条主账各自被挂到一个早已走过的章上，而後无人再问。**
    #   ⛔**这正是「一盏没灭过的灯」**：**一道永远绿的闸，等於没有这道闸。**
    #   ★★★**故补此问**：**逾限者，其哨须落在末章之後**（`哨 > 末`）；**落在末章或其前者，当场红。**
    #   ⛔**此改令本格更严，不更宽**——**它此後逮得着「挂了一个早就过去的哨」这一样。**
    _朽 = [(k, 哨章.get(k)) for k, 末见, 距, bad in 报
           if bad and 哨章.get(k) and int(哨章.get(k)) <= 末]
    if _朽:
        # 〔1119 死规之审·gates15〕逾限而其哨已朽 → 只报 ⚠（⛔return False）：⛔再逼改挂哨章
        return True, ('%s·⚠距逾其限而其哨已朽（只报·1119 死规之审；哨落在末章%d或其前）：%s'
                      % (m.group(0), 末, '、'.join('%s→哨%s' % x for x in _朽)))
    逾 = [(k, 距, 哨章.get(k)) for k, 末见, 距, bad in 报 if bad]
    if 逾:
        return True, ('%s·逾限 %d 笔皆已挂哨：%s'
                      % (m.group(0), len(逾),
                         '、'.join('%s(隔%d章→挂%s)' % x for x in 逾)))
    return True, '%s·三条主账皆在限内' % m.group(0)


def chk_zhangjian():
    """★到期账「一样东西只许一个键名」之负测（2026-09-13 立）：
    ⛔**其事**：一笔账销了，其章写在哪个键上，盘上曾有三种写法——
      **`清偿章` 133 笔｜`结账章` 11 笔｜`清账章` 1 笔**；**而 `书级体检::check_due_net` 只读 `清偿章`**。
      ★**故那十二笔在账上看着已销，在闸眼里从来没有销过**（296／298／301／307／328 皆有）。
    ★★**其害不在某一笔**：**净额那一条闸量的是「开的线与收的线之差」**——
      **收的那一头漏掉十二笔，它报出来的红就不是书的红，是键名的红。**
    ★★★**其牙**：③格拿一笔造出来的销回灌，净额须落一格；④格证别名写法体检当真不认。"""
    out = run('负测·账键一名', ['工具/负测_账键一名.py'])
    if out is None:
        return False, '运行失败'
    import re as _r
    m = _r.search(r'(\d+)/(\d+) (全通|有败)', out)
    if not m:
        return False, '未见其数'
    ok, tot, 判 = int(m.group(1)), int(m.group(2)), m.group(3)
    if 判 != '全通' or ok != tot:
        _b = [ln.strip() for ln in out.splitlines() if ln.strip().startswith('⛔')]
        return False, '；'.join(_b[:3]) or '%d/%d' % (ok, tot)
    return True, '%d/%d 全通（③销落进去净额须落一格·④别名不认）' % (ok, tot)


def chk_weight_trend():
    """★净重之趋（2026-09-13 立·本器头一回跑就跑出九十章之实）：
    ★★守一句——**末一段若比上一段跌逾一成半，册上须有一行裁；无裁即拦。**
    ⛔**其所以要立**：盘上诸闸皆逐章而问（章型带／棘轮预检／字数闸）
      ——**而「全书在慢慢变薄」这件事不在任何一章里**：**每章只比上章少一点点，十五章之後就是三成。**
      ★**0913 之实**：**顶在 223—237（中位 7,076），今 313—327 中位 2,216——九十章落了 68.7%。**
    ★★★**本器不判该不该**（一站之末在原地量本来就该薄）——**它只逼出一行裁**；
      ⛔**写不出其由的，就是那一段真的薄了。**"""
    out = run('净重之趋·自测', ['工具/净重趋.py', '--自测'])
    if out is None:
        return False, '运行失败'
    import re as _r
    m = _r.search(r'自测 (\d+)/(\d+)', out)
    if not m or m.group(1) != m.group(2):
        return False, '自测未满格：%s' % (m.group(0) if m else '未见其数')
    # ★末一段若报红，册上须有一行裁（认其段之首章之号）
    out2 = run('净重之趋', ['工具/净重趋.py'])
    if out2 is None:
        return False, '正路运行失败'
    reds = _r.findall(r'⚠ 第(\d+)—(\d+)章', out2)
    if not reds:
        return True, '%s·无一段跌逾一成半' % m.group(0)
    末 = reds[-1]
    import glob as _g, io as _io, os as _os
    有裁 = False
    for f in _g.glob(_os.path.join(ROOT, '设定', '*裁*净重之趋*.md')):
        t = _io.open(f, encoding='utf-8', errors='replace').read()
        if 末[0] in t and 末[1] in t:
            有裁 = True
    if not 有裁:
        return False, ('⛔末一段第%s—%s章跌逾一成半而册上无一行裁'
                       '——写不出其由的，就是那一段真的薄了' % 末)
    return True, '%s·末段第%s—%s章之跌已有一行裁在册上' % (m.group(0), 末[0], 末[1])



