        ok = ok and r.returncode == 0
        末 = (r.stdout.strip().split('\n') or [''])[-1]
        if r.returncode != 0:
            错 = ([l.strip() for l in (r.stderr or '').split('\n') if l.strip()] or ['（stderr 无印）'])[-1]
            末 = '⛔%s rc=%d：%s｜%s' % (os.path.basename(路), r.returncode, 错[:90], 末[:60])
