def chk_fayong():
    """法用之守（1027）：今之状——完备之律（总章§八与方法账 1027 起之行俱有册之据）、册之形、逾限之待（只报·入器红账）。"""
    out = run('法用之守', ['工具/法用之守.py', '--报'], timeout=120)
    if out is None:
        return False, '运行失败（崩或逾时）'
    末 = [x.strip() for x in out.strip().split('\n') if x.strip()]
    语 = 末[-1] if 末 else '（无印）'
    return 语.startswith('✓'), 语[:170]


def chk_paozhang():
    """★囤灰闸问「接没接上」，本项问「**跑没跑过**」——两问不同，缺一样都不够。
    ★★其红黄之别由 工具/跑账.py 自己判（立账之日以前无凭者只报黄）；本项只把它的话搬过来。
    """
    try:
        import subprocess
        r = subprocess.run(['python3', os.path.join(ROOT, '工具', '跑账.py')],
                           capture_output=True, text=True, timeout=120)
        末 = [x.strip() for x in (r.stdout or '').strip().split('\n') if x.strip()]
        语 = 末[1] if len(末) > 1 else (末[0] if 末 else '（跑账无话）')
        # 〔W908 环7〕GitHub 之机无跑迹（_器之迹 唯沙盒有）：甲路恒「无凭」只 ⚠——其判归 封版 --後 之活态（封版.活态之格）；乙路之红（rc≠0）照报
        if r.returncode == 0 and 在GitHub():
            语 = '沙盒专·封版活态判（GitHub 之机无跑迹：甲路之「无凭」⛔判；乙路无红）'
        return (r.returncode == 0), 语[:160]
    except Exception as e:
        return False, '跑账跑不起来：%s' % e


def _记器账(录, quick):
    """★1015 W35·作者令「工具也要有升级和进化之机制，发现其 bug 与瑕疵」——虹吸：每推本就跑全测，顺手记每检之果、之秒、之红，
    器之健康之数自流（零 token）；工具/囤灰闸.py --普查 读之，列候修（假红多、慢）、候退（久无红、唯自测）。
    档 `_器之账.json` 係跑起来的痕（.gitignore；存底.py 强塞入存底枝），⛔入主枝。记坏⛔碍全测。"""
    try:
        import json as _j
        p = os.path.join(ROOT, '_器之账.json')
        账 = _j.load(open(p, encoding='utf-8')) if os.path.exists(p) else {}
        今 = time.strftime('%m%d %H:%M')
        for 名, ok, 秒, 说 in 录:
            x = 账.setdefault(名, {'跑': 0, '红': 0, '秒均': 0.0, '红史': []})
            x['跑'] += 1
            if not quick:
                x['秒均'] = round(秒 if x['跑'] == 1 else 0.7 * x['秒均'] + 0.3 * 秒, 2)
                x['秒末'] = round(秒, 2)
            x['末跑'] = 今
            if not ok:
                x['红'] += 1
                x['红史'] = (x['红史'] + [[今, 说[:200]]])[-10:]
        _j.dump(账, open(p, 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
    except Exception as e:
        print('  ⚠ 器之账未记（%s）——不碍全测' % e)


