# ═══ 片去活态（1117·GitHub 化之审·H·法用#片去活态）═══
# ★GitHub 之片闸（gate.yml：--片数／--片／--并果）免「活态之格」——其判唯取沙盒之现场，GitHub 之机上其现场恒空恒新、绿而无所证：
#   接力：心跳之锁（远端 备份/心跳 之一瞬）、`版本/第N+1章/` 与 `_十一轮.json` 之 mtime（GitHub 上即 checkout 之刻·静恒数十秒）、
#     续跑之步（_任务流.json·.gitignore）——其「判」之唯一之红（断流）须「静逾二十五分」或二档俱无，章-411—459 之树俱有二档 → GitHub 上判红不起
#     （二档俱无之局，_十一轮.json 不在即十一轮哨已红）；报/推 之迹（备份/报·1027—1117）121 跑俱 ✓ 而其语恒一（不停之律⑤之印行：⛔一跑见断流之行）。
#   ★★而「崩」红得起（1117 H 审之变异所逮·旧注「GitHub 上红不起」误）：接力.py 之真跑之路／印之块随树、随码而崩（变异 print('  ✓ 接上了。' % 下)），
#     旧唯此真跑逮之（器红·只报·限三章）——今其守归 负测·接力（接力.py --自测 ⑰—⑳：印=True 诸支、心跳() 之读、真树之读、入口 主()·读者可见·红即拦）。
#   ⛔余活态（全测并.活态＝接力、跑账、负测·自进化环、钩子挂载）不免：跑账之乙路（注没注上）、钩子挂载之「pre-push 在盘」、负测·自进化环之自测——俱判树，GitHub 上红得起。
#   沙盒：每章之流唯 封版 --後 之活态之报（封版.活态之格）跑接力——只报⚠、⛔拦、红入器红账；全测（串／并）唯 pre-push 之非暂存之推与手跑。
#   降级：活态免GitHub = False 即复旧（一处之开关·⛔改 workflow：治推即生效）；名单之名有不在表者（改名、删格）即⛔免而全跑（旧式）；
#     并判之表纹：诸片所跑为全表（旧式）亦认（全测并.并判）。
活态免GitHub = True
活态之格 = ('接力',)


def 在GitHub():
    return os.environ.get('GITHUB_ACTIONS') == 'true'


def 活态之免(名们, 免=None):
    """→ (所免之名们, 缺)：GitHub 片闸所免之格。免 None 即「活态免GitHub 且 在GitHub()」；不免、或名单之名有不在表者（缺）→ 所免为 ()（全跑·旧式）。⛔印（--片数 之 stdout 唯片数）。"""
    免 = (活态免GitHub and 在GitHub()) if 免 is None else 免
    if not 免:
        return (), []
    缺 = [x for x in 活态之格 if x not in 名们]
    return (() if 缺 else tuple(活态之格)), 缺


def 闸之诸项(quick, 免=None):
    """GitHub 片闸之项表（--片数、--片、--并果 同取此一函·⛔各算）：诸项去 活态之免；沙盒（非 GitHub）即诸项。"""
    项 = 诸项(quick)
    去, _ = 活态之免([x for x, _ in 项], 免)
    return [(x, f) for x, f in 项 if x not in 去]


def 活态之语(名们, 免=None):
    """片闸之印之一行（片跑之头、并判之末）：所免、或降级之⚠；不免即空。"""
    去, 缺 = 活态之免(名们, 免)
    if 缺:
        return '⚠ 活态之格 %s 不在全测之表——GitHub 片闸⛔免、全跑（旧式·法用#片去活态之降级）' % '、'.join(缺)
    if 去:
        return '· 活态免（GitHub·法用#片去活态）：%s——沙盒之全测与封版之活态之报照跑；复旧：全测.活态免GitHub = False' % '、'.join(去)
    return ''


def 只跑(名们, 出, quick):
    """★1017 W51：`--只 名,… [--出 档]`——只跑所列之项（取自 诸项()，⛔另写），每项印一行同 main；
    以 JSON 交其果 {果: [[名, 过, 语, 秒]], 未认: [...]} 於 出（全测并.py 於工作副本中逐项调之）。
    ⛔不记器账、⛔不查留字（并行之驱於副本以 git status 查之、主仓库之项以 _留字快照 查之）。"""
    表 = dict(诸项(quick))
    果, 未认 = [], [n for n in 名们 if n not in 表]
    for 名 in 名们:
        if 名 not in 表:
            continue
        _t0 = time.time()
        try:
            ok, detail = 表[名]()
        except Exception as _e:
            ok, detail = False, '⛔器崩：%r' % (_e,)
        果.append([名, bool(ok), str(detail), round(time.time() - _t0, 2)])
        print('  %s %-14s %s' % ('✓' if ok else '✗', 名, detail))
    if 出:
        import json as _j
        _j.dump({'果': 果, '未认': 未认}, open(出, 'w', encoding='utf-8'), ensure_ascii=False)
    return 0 if (not 未认 and all(x[1] for x in 果)) else 1


def 片跑(k, n, 出, quick, 秒档=None):
    """★1027 坑54：`--片 k/N --出 档 [--秒表 档]`——GitHub 分片之闸之一片（autopush、演练之 shard 之阵）。
    诸项照 全测并.分片（LPT·定式：同一秒表，诸片各算皆同、每格恰在一片）取第 k 片，於候之树上串跑（同 main：留字以快照、带席之判同）；
    每跑一格即落 出（逾时被杀亦存已跑者，并判见其缺）。⛔推闸、⛔记器账——判在并判（全测并.并判）。→ 0 俱绿｜1 有红"""
    import json as _j
    import 全测并 as _并
    全名 = [x for x, _ in 诸项(quick)]
    项 = 闸之诸项(quick)                      # ★1117 片去活态：GitHub 上免活态之格（沙盒即全表）
    表, 名们 = dict(项), [x for x, _ in 项]
    我 = _并.分片(名们, _并.秒表(秒档), n)[k - 1]
    sha = subprocess.run(['git', 'rev-parse', 'HEAD'], cwd=ROOT, capture_output=True, text=True).stdout.strip()
    d = {'片': k, '数': n, 'sha': sha, '表': _并.表纹(名们), '快': bool(quick), '名们': 我, '果': [], '留字': [], '席凭': [], '秒': 0, '毕': False,
         '免': [x for x in 全名 if x not in 表]}

    def 落():
        if 出:
            os.makedirs(os.path.dirname(os.path.abspath(出)), exist_ok=True)
            _j.dump(d, open(出, 'w', encoding='utf-8'), ensure_ascii=False)
    print('\n████ 全测·片 %d/%d · %d 项（共 %d）· %s ████' % (k, n, len(我), len(名们), sha[:12]))
    if 活态之语(全名):
        print('  ' + 活态之语(全名))
    落()
    t0, 快照 = time.time(), _留字快照()
    for 名 in 我:
        _t = time.time()
        try:
            ok, detail = 表[名]()
        except Exception as _e:
            ok, detail = False, '⛔器崩：%r' % (_e,)
        d['果'].append([名, bool(ok), str(detail), round(time.time() - _t, 2)])
        print('  %s %-14s %s' % ('✓' if ok else '✗', 名, detail))
        落()
    变, 增, 失 = _留字之差(快照)
    d.update(留字=变 + 增 + 失, 席凭=_有席在跑() if (变 or 增 or 失) else [], 秒=round(time.time() - t0, 2), 毕=True)
    落()
    红 = [x[0] for x in d['果'] if not x[1]]
    print('  · 片 %d/%d：%d 项、红 %d、留字 %d、%.0f 秒' % (k, n, len(我), len(红), len(d['留字']), d['秒']))
    return 0 if not 红 and not d['留字'] else 1


def _参(a, k, 缺=None):
    return a[a.index(k) + 1] if k in a and a.index(k) + 1 < len(a) else 缺


def 补浅克隆():
    """★1022 W64（403 推闸逮）：云端会话係浅克隆，负测之钉於旧笔者（负测·全测崩绿之 a73c8836、负测·含拍）git show 得空而诬红——先补全史一回（零 token；已全者不动）。"""
    try:
        if subprocess.run(['git', 'rev-parse', '--is-shallow-repository'], cwd=ROOT, capture_output=True, text=True).stdout.strip() == 'true':
            subprocess.run(['git', 'fetch', '-q', '--unshallow', 'origin'], cwd=ROOT, capture_output=True, timeout=600)
    except Exception:
        pass


def main():
    quick = '--快' in sys.argv
    _a = sys.argv
    # ★1027 坑54：GitHub 分片之闸三口——--片数（备候者择 N）、--片 k/N（一片）、--并果（诸片之果并判·推闸同策）
    if '--片数' in _a:
        import 全测并 as _并
        n, 诸 = _并.择片数([x for x, _ in 闸之诸项(quick)], _并.秒表(_参(_a, '--秒表')))   # ★1117 片去活态：与 --片、--并果 同表
        print(n)
        print('  · 诸片数之关键路（秒）：%s' % '、'.join('%d→%.0f' % kv for kv in sorted(诸.items())), file=sys.stderr)
        if 活态之语([x for x, _ in 诸项(quick)]):
            print('  ' + 活态之语([x for x, _ in 诸项(quick)]), file=sys.stderr)
        return 0
    if '--并果' in _a:
        import 全测并 as _并
        return _并.并判口(_a, quick)
    if '--片' in _a:
        补浅克隆()
        k, n = (int(x) for x in _参(_a, '--片', '').split('/'))
        if not 1 <= k <= n:
            print('⛔ --片 k/N：须 1≤k≤N（今 %d/%d）' % (k, n))
            return 2
        return 片跑(k, n, _参(_a, '--出'), quick, _参(_a, '--秒表'))
    补浅克隆()
    if '--只' in sys.argv:
        _a = sys.argv
        _名 = [x for x in _a[_a.index('--只') + 1].split(',') if x] if _a.index('--只') + 1 < len(_a) else []
        _出 = _a[_a.index('--出') + 1] if '--出' in _a and _a.index('--出') + 1 < len(_a) else None
        return 只跑(_名, _出, quick)
    items = 诸项(quick)
    print('\n████ 全测 · %d 项 ████' % len(items))
    _席凭 = _有席在跑()
    if _席凭:
        print('  ⚠ **本次係带席而跑**（%s）——**下列诸红须逐条分辨真假**：'
              '正在写的那一章尚无席记、下一章尚无开镜卡，皆係时序不是病。'
              '★待席收毕、仓里安静时再跑一回，那一回才算数。' % '、'.join(_席凭))
        print('     ★**带席而跑时，这几道多半是同一个根**（0910 实查）：'
              '席每改一轮文，**阅读器即过期**，而 检察官自测／医生／全书检 三项俱据之报红；'
              '而阅读器是封版之序才重生的。**三红一根，不是三处病。**')
    fails = []
    跑过件数 = [0]
    _快照 = _留字快照()
    _器录 = []
    for name, fn in items:
        跑过件数[0] += 1
        _t0 = time.time()
        ok, detail = fn()
        _器录.append((name, bool(ok), time.time() - _t0, str(detail)))
        print('  %s %-14s %s' % ('✓' if ok else '✗', name, detail))
        if not ok:
            fails.append(name)
    _记器账(_器录, quick)
    # ★负测留字之查（2026-09-05）：跑毕再照一回，凡 设定／版本／正文 之内容有变、有增、有失者，即负测留字。
    _变, _增, _失 = _留字之差(_快照)
    if _变 or _增 or _失:
        席凭 = _有席在跑()
        if 席凭:
            # ★带席而跑：这几档多半是那一席正在写的，**不是负测偷改的**。
            #   报黄、写明其凭，**不入 fails**——否则一道假红会把一章的封版推闸堵死。
            print('  ⚠ %-14s **本次係带席而跑**（%s）：内容有变 %d｜新增 %d｜消失 %d：%s' % (
                '负测留字', '、'.join(席凭), len(_变), len(_增), len(_失),
                '、'.join((_变 + _增 + _失)[:6])))
            print('     ★下列诸红须逐条分辨真假；**待席收毕、仓里安静时再跑一回全测**，那一回它才算数。')
        else:
            print('  ✗ %-14s 内容有变 %d｜新增 %d｜消失 %d：%s' % (
                '负测留字', len(_变), len(_增), len(_失), '、'.join((_变 + _增 + _失)[:6])))
            print('     ★某份负测改了真仓库之档而未复原（多半是中途崩了或被超时所杀）——先 git diff 看它改了什么，再定复原。')
            fails.append('负测留字')
    else:
        print('  ✓ %-14s 设定／版本／正文 %d 档，跑前跑後 sha256 逐档同' % ('负测留字', len(_快照)))
    if 跑过件数[0] < (最少件数 if not quick else 8):
        print('\n  ⛔空跑闸：本次只跑了 %d 件（至少 %d）——多半是 main() 被截断或 items 没接上。'
              % (跑过件数[0], 最少件数 if not quick else 8))
        print('     ★此病长得跟全绿一模一样：rc=0、一行不印。**退出码不是印**（令§一②）。')
        return 1
    if fails:
        print('\n  ⛔全测未过：%s' % '、'.join(fails))
        ok, 语 = 推闸(fails, [n for n, _ in items])
        print('  %s' % 语)
        if not ok:
            print('  【批115】不过不许推——pre-push 钩子据此拦停。')
        return 1
    推闸([], [n for n, _ in items])          # 1027 坑54：俱绿亦更器红账——所跑之格俱销（⛔留旧首见，复红时误判逾限）
    print('\n  ✓全测通过%s。' % ('（快测，未含全书检）' if quick else ''))
    return 0


if __name__ == '__main__':
    sys.exit(main())
